                {
                    { 1563703640072386612L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Giữ đuôi い và thêm です để miêu tả lịch sự. この本はおもしろいです。 nghĩa là Quyển sách này thú vị.", 1563703640072386512L, "vi", "Tính từ đuôi い", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Một số từ như きれい kết thúc bằng âm i nhưng thuộc nhóm tính từ な.", 1L },
                    { 1563703640072386613L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Keep the final い and add です for a polite description. この本はおもしろいです。 means This book is interesting.", 1563703640072386512L, "en", "Affirmative i-adjectives", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Some words ending in the sound i, such as きれい, are na-adjectives.", 1L },
                    { 1563703640072386614L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Bỏ い cuối rồi thêm くないです. この部屋は寒くないです。 nghĩa là Phòng này không lạnh.", 1563703640072386513L, "vi", "Phủ định tính từ い", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "いい đổi thành よくないです. Cũng có thể dùng くありません.", 1L },
                    { 1563703640072386615L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Replace the final い with くないです. この部屋は寒くないです。 means This room is not cold.", 1563703640072386513L, "en", "Negative i-adjectives", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "いい becomes よくないです. The form くありません is another polite option.", 1L },
                    { 1563703640072386616L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Thay い bằng かったです khi khẳng định quá khứ, hoặc くなかったです khi phủ định. 昨日は寒かったです。 nghĩa là Hôm qua trời lạnh.", 1563703640072386514L, "vi", "Quá khứ của tính từ い", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "いい dùng gốc よ, như よかったです và よくなかったです.", 1L },
                    { 1563703640072386617L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Replace the final い with かったです for the affirmative past, or くなかったです for the negative past. 昨日は寒かったです。 means It was cold yesterday.", 1563703640072386514L, "en", "Past i-adjectives", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "いい uses the stem よ, as in よかったです and よくなかったです.", 1L },
                    { 1563703640072386618L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Thêm です khi kết thúc câu và な khi bổ nghĩa danh từ. 静かな部屋です。 nghĩa là Đây là một căn phòng yên tĩnh.", 1563703640072386515L, "vi", "Tính từ な", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Không thêm な ngay trước です. Phủ định có thể dùng ではありません.", 1L },
                    { 1563703640072386619L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use です at the end of a sentence and な before a modified noun. 静かな部屋です。 means It is a quiet room.", 1563703640072386515L, "en", "Na-adjectives", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Do not insert な directly before です. A polite negative uses ではありません.", 1L },
                    { 1563703640072386620L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đặt tính từ trước danh từ. 新しい車 và 便利な店 lần lượt nghĩa là xe mới và cửa hàng tiện lợi.", 1563703640072386516L, "vi", "Miêu tả danh từ", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Tính từ い giữ い, còn tính từ な cần な trong dạng khẳng định hiện tại.", 1L },
                    { 1563703640072386621L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Put the adjective before the noun. 新しい車 means a new car, and 便利な店 means a convenient shop.", 1563703640072386516L, "en", "Modifying nouns with adjectives", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "An i-adjective retains い, while a na-adjective takes な in an affirmative non-past modifier.", 1L },
                    { 1563703640072386622L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng が để đánh dấu đối tượng được thích hoặc không thích. 猫が好きです。 nghĩa là Tôi thích mèo.", 1563703640072386517L, "vi", "Thích và không thích", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "好き và 嫌い thuộc nhóm tính từ な. Chủ thể có thể được nêu bằng は khi cần.", 1L },
                    { 1563703640072386623L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use が to mark what someone likes or dislikes. 猫が好きです。 means I like cats.", 1563703640072386517L, "en", "Likes and dislikes", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "好き and 嫌い are na-adjectives. A topic marked with は can identify whose preference is described.", 1L },
                    { 1563703640072386624L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng 欲しい để nói mong muốn có một vật. 新しいかばんが欲しいです。 nghĩa là Tôi muốn một chiếc túi mới.", 1563703640072386518L, "vi", "Muốn có một thứ gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Trong câu khẳng định thông thường, mẫu này diễn đạt mong muốn của người nói. Có thể hỏi mong muốn của người nghe.", 1L },
                    { 1563703640072386625L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use 欲しい for wanting an object. 新しいかばんが欲しいです。 means I want a new bag.", 1563703640072386518L, "en", "Wanting something", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "In a normal affirmative statement this describes the speaker's desire. It can also ask about the listener's desire.", 1L },
                    { 1563703640072386626L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Bỏ ます khỏi dạng lịch sự rồi thêm たいです. 日本語を勉強したいです。 nghĩa là Tôi muốn học tiếng Nhật.", 1563703640072386519L, "vi", "Muốn làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "たい chia như tính từ い. Với mong muốn của người thứ ba cần ngữ cảnh hoặc cách diễn đạt phù hợp.", 1L },
                    { 1563703640072386627L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Remove ます from the polite verb form and add たいです. 日本語を勉強したいです。 means I want to study Japanese.", 1563703640072386519L, "en", "Wanting to do something", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "たい inflects like an i-adjective. Statements about another person's desire require suitable context or wording.", 1L },
                    { 1563703640072386628L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng に hoặc へ sau địa điểm đích của động từ di chuyển. 学校に行きます。 nghĩa là Tôi đi đến trường.", 1563703640072386520L, "vi", "Đích đến", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "へ khi là trợ từ được đọc là e. Đây là cách dùng chỉ đích, khác cách dùng に chỉ thời điểm.", 1L },
                    { 1563703640072386629L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use に or へ after the destination of a movement verb. 学校に行きます。 means I go to school.", 1563703640072386520L, "en", "Destinations", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "The particle へ is read e. This destination use of に differs from its time use.", 1L },
                    { 1563703640072386630L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng で sau phương tiện di chuyển. バスで会社に行きます。 nghĩa là Tôi đi xe buýt đến công ty.", 1563703640072386521L, "vi", "Phương tiện di chuyển", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đi bộ thường nói 歩いて行きます.", 1L },
                    { 1563703640072386631L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Mark a means of transport with で. バスで会社に行きます。 means I go to work by bus.", 1563703640072386521L, "en", "Transport with de", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "For going on foot, the usual expression is 歩いて行きます.", 1L },
                    { 1563703640072386632L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng と sau người cùng thực hiện hành động. 友達と映画を見ます。 nghĩa là Tôi xem phim cùng bạn.", 1563703640072386522L, "vi", "Làm cùng ai", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "一人で diễn đạt làm một mình.", 1L },
                    { 1563703640072386633L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use と after a person who takes part in an action with someone. 友達と映画を見ます。 means I watch a film with a friend.", 1563703640072386522L, "en", "Doing something with someone", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "一人で expresses doing something alone.", 1L },
                    { 1563703640072386634L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "から chỉ điểm bắt đầu, まで chỉ điểm kết thúc trong thời gian hoặc không gian. 九時から五時まで働きます。 nghĩa là Tôi làm việc từ chín giờ đến năm giờ.", 1563703640072386523L, "vi", "Từ và đến", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Có thể dùng riêng から hoặc まで khi chỉ cần nêu một mốc.", 1L },
                    { 1563703640072386635L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "から marks a starting point and まで an endpoint in time or space. 九時から五時まで働きます。 means I work from nine to five.", 1563703640072386523L, "en", "From and until", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Either particle can be used on its own when only one boundary is relevant.", 1L },
                    { 1563703640072386636L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đặt trạng từ tần suất trong câu để diễn đạt mức độ thường xuyên. 時々コーヒーを飲みます。 nghĩa là Tôi thỉnh thoảng uống cà phê.", 1563703640072386524L, "vi", "Tần suất", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ở cách dùng nhập môn, あまり và 全然 đi với phủ định, như あまり飲みません.", 1L },
                    { 1563703640072386637L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use frequency adverbs to describe how often an action occurs. 時々コーヒーを飲みます。 means I sometimes drink coffee.", 1563703640072386524L, "en", "Frequency", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "In introductory usage, あまり and 全然 accompany a negative, as in あまり飲みません.", 1L },
                    { 1563703640072386638L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng Vませんか để mời, Vましょう để đề nghị cùng làm. 一緒に昼ご飯を食べませんか。 nghĩa là Bạn có muốn ăn trưa cùng không?", 1563703640072386525L, "vi", "Mời và rủ cùng làm", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "ませんか ở đây là lời mời lịch sự. Có thể trả lời bằng いいですね rồi dùng ましょう.", 1L },
                    { 1563703640072386639L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use Vませんか to invite and Vましょう to suggest doing something together. 一緒に昼ご飯を食べませんか。 means Would you like to have lunch together?", 1563703640072386525L, "en", "Invitations and suggestions", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Here ませんか is a polite invitation. A positive response can use いいですね followed by ましょう.", 1L },
                    { 1563703640072386640L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nhóm 2 bỏ る rồi thêm て. Nhóm 1 đổi đuôi theo nhóm âm, như 読む thành 読んで và 書く thành 書いて. する thành して, 来る thành 来て（きて）.", 1563703640072386526L, "vi", "Cách tạo thể て", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nhóm 1 có う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで, す → して. 行く là ngoại lệ 行って. Nhóm động từ phải được học cùng từ.", 1L },
                    { 1563703640072386641L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "For group 2 verbs replace る with て. Group 1 endings change by sound group, as in 読む to 読んで and 書く to 書いて. する becomes して and 来る becomes 来て（きて）.", 1563703640072386526L, "en", "Forming the te-form", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Group 1 uses う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで and す → して. 行く is the exception 行って. Learn each verb's group with the word.", 1L },
                    { 1563703640072386642L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nối thể て với ください để yêu cầu hoặc hướng dẫn. ここに名前を書いてください。 nghĩa là Hãy viết tên vào đây.", 1563703640072386527L, "vi", "Nhờ hoặc yêu cầu làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Với người có vai vế cao hoặc tình huống cần trang trọng hơn, cần chọn cách nhờ phù hợp.", 1L },
                    { 1563703640072386643L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Add ください to the te-form for a request or instruction. ここに名前を書いてください。 means Please write your name here.", 1563703640072386527L, "en", "Requests with te kudasai", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Choose a more suitable request form when hierarchy or formality requires it.", 1L },
                    { 1563703640072386644L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng ています để nói hành động đang diễn ra. 今、本を読んでいます。 nghĩa là Bây giờ tôi đang đọc sách.", 1563703640072386528L, "vi", "Hành động đang diễn ra", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Ý nghĩa tùy động từ. Với một số động từ, ています thể hiện trạng thái kết quả, như 結婚しています.", 1L },
                    { 1563703640072386645L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use ています for an action in progress. 今、本を読んでいます。 means I am reading a book now.", 1563703640072386528L, "en", "Actions in progress", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "The interpretation depends on the verb. Some verbs use ています for a resulting state, as in 結婚しています.", 1L },
                    { 1563703640072386646L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng てもいいです để nói được phép và thêm か để xin phép. ここに座ってもいいですか。 nghĩa là Tôi ngồi đây được không?", 1563703640072386529L, "vi", "Xin phép và cho phép", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Khi từ chối, cần chọn cách nói phù hợp với quan hệ và tình huống.", 1L },
                    { 1563703640072386647L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use てもいいです for permission and add か to ask for it. ここに座ってもいいですか。 means May I sit here?", 1563703640072386529L, "en", "Asking and giving permission", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Choose a contextually appropriate expression when refusing permission.", 1L },
                    { 1563703640072386648L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng てはいけません để nêu điều không được làm. ここで写真を撮ってはいけません。 nghĩa là Không được chụp ảnh ở đây.", 1563703640072386530L, "vi", "Điều cấm", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Mẫu này khá trực tiếp, thường dùng để giải thích nội quy hoặc quy định.", 1L },
                    { 1563703640072386649L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use てはいけません to state a prohibition. ここで写真を撮ってはいけません。 means You must not take photographs here.", 1563703640072386530L, "en", "Prohibitions", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "This is a direct expression often used for rules and regulations.", 1L },
                    { 1563703640072386650L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng thể て để nối các hành động theo ngữ cảnh. 朝ご飯を食べて、学校に行きます。 nghĩa là Tôi ăn sáng rồi đi học.", 1563703640072386531L, "vi", "Nối các hành động", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Động từ cuối quyết định mức lịch sự và thời của toàn chuỗi.", 1L },
                    { 1563703640072386651L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use the te-form to connect actions in context. 朝ご飯を食べて、学校に行きます。 means I eat breakfast and then go to school.", 1563703640072386531L, "en", "Sequencing actions", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "The final verb determines the politeness and tense of the sequence.", 1L },
                    { 1563703640072386652L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nhóm 2 bỏ る và thêm ない. Nhóm 1 đổi âm u cuối sang hàng a rồi thêm ない, như 書く thành 書かない. する thành しない, 来る thành 来ない（こない）.", 1563703640072386532L, "vi", "Thể phủ định ない", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Động từ nhóm 1 tận cùng う đổi thành わない, như 買う → 買わない. ある phủ định là ない.", 1L },
                    { 1563703640072386653L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "For group 2 replace る with ない. For group 1 change the final u sound to its a-row counterpart and add ない, as in 書く to 書かない. する becomes しない and 来る becomes 来ない（こない）.", 1563703640072386532L, "en", "Forming the nai-form", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Group 1 verbs ending in う take わない, as in 買う → 買わない. The negative of ある is ない.", 1L },
                    { 1563703640072386654L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng thể ない rồi thêm でください để yêu cầu đừng làm. ここで走らないでください。 nghĩa là Xin đừng chạy ở đây.", 1563703640072386533L, "vi", "Yêu cầu đừng làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đây là mẫu yêu cầu phủ định. Tránh nhầm với なくて dùng trong những cấu trúc nối khác.", 1L },
                    { 1563703640072386655L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Add でください to the nai-form to ask someone not to act. ここで走らないでください。 means Please do not run here.", 1563703640072386533L, "en", "Asking someone not to do something", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "This is a negative request. Distinguish ないで from なくて in other linking structures.", 1L },
                    { 1563703640072386656L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Thay ない bằng なければなりません để diễn đạt nghĩa vụ. 薬を飲まなければなりません。 nghĩa là Tôi phải uống thuốc.", 1563703640072386534L, "vi", "Phải làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Trong hội thoại còn gặp ないといけません và những dạng rút gọn tùy mức lịch sự.", 1L },
                    { 1563703640072386657L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Replace ない with なければなりません to express an obligation. 薬を飲まなければなりません。 means I must take medicine.", 1563703640072386534L, "en", "Obligation", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Conversation also uses ないといけません and contractions depending on the register.", 1L },
                    { 1563703640072386658L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Thay ない bằng なくてもいいです để nói không cần làm. 明日は来なくてもいいです。 nghĩa là Ngày mai bạn không cần đến.", 1563703640072386535L, "vi", "Không cần phải làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Mẫu này bỏ yêu cầu thực hiện hành động, không diễn đạt điều cấm.", 1L },
                    { 1563703640072386659L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Replace ない with なくてもいいです to say an action is unnecessary. 明日は来なくてもいいです。 means You do not have to come tomorrow.", 1563703640072386535L, "en", "Lack of obligation", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "This removes the obligation to act. A prohibition requires a different expression.", 1L },
                    { 1563703640072386660L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng dạng từ điển trước ことができます để diễn đạt khả năng hoặc điều có thể làm. 日本語を読むことができます。 nghĩa là Tôi có thể đọc tiếng Nhật.", 1563703640072386536L, "vi", "Có thể làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Danh từ chỉ hoạt động cũng có thể đi với ができます, như 料理ができます.", 1L },
                    { 1563703640072386661L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Place the dictionary form before ことができます to express ability or possibility. 日本語を読むことができます。 means I can read Japanese.", 1563703640072386536L, "en", "Ability with koto ga dekimasu", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "An activity noun can also precede ができます, as in 料理ができます.", 1L },
                    { 1563703640072386662L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng dạng từ điển trước 前に và thể た trước 後で. 寝る前に、本を読みます。 nghĩa là Tôi đọc sách trước khi ngủ.", 1563703640072386537L, "vi", "Trước và sau hành động", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Với danh từ thường dùng Nの前に và Nの後で. Thể trước 前に không đổi theo thời của động từ cuối.", 1L },
                    { 1563703640072386663L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use the dictionary form before 前に and the ta-form before 後で. 寝る前に、本を読みます。 means I read a book before going to bed.", 1563703640072386537L, "en", "Before and after an action", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "With nouns use Nの前に and Nの後で. The form before 前に stays in the dictionary form even when the final verb is past.", 1L },
                    { 1563703640072386664L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng cùng quy tắc biến đổi âm như thể て nhưng đổi て thành た và で thành だ. 書く → 書いた, 読む → 読んだ, 食べる → 食べた.", 1563703640072386538L, "vi", "Thể quá khứ ngắn た", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "する → した, 来る → 来た（きた）, 行く → 行った. Dạng này còn xuất hiện trong các cấu trúc ngoài câu quá khứ độc lập.", 1L },
                    { 1563703640072386665L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Apply the te-form sound changes, replacing て with た and で with だ. Examples include 書く → 書いた, 読む → 読んだ and 食べる → 食べた.", 1563703640072386538L, "en", "Forming the ta-form", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "する → した, 来る → 来た（きた） and 行く → 行った. The form also appears inside structures other than independent past statements.", 1L },
                    { 1563703640072386666L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng thể た trước ことがあります để nói về trải nghiệm đã có. 日本に行ったことがあります。 nghĩa là Tôi đã từng đến Nhật Bản.", 1563703640072386539L, "vi", "Đã từng làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Để kể một sự kiện tại thời điểm quá khứ cụ thể, thường dùng câu quá khứ thông thường.", 1L },
                    { 1563703640072386667L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use the ta-form before ことがあります to describe a past experience. 日本に行ったことがあります。 means I have been to Japan.", 1563703640072386539L, "en", "Past experience", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use an ordinary past statement when reporting a specific event at a particular past time.", 1L },
                    { 1563703640072386668L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Thêm り vào thể た để liệt kê vài hoạt động tiêu biểu. 休みの日は本を読んだり、映画を見たりします。 nghĩa là Ngày nghỉ tôi đọc sách, xem phim và làm những việc tương tự.", 1563703640072386540L, "vi", "Liệt kê vài hoạt động", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Danh sách có tính ví dụ. Động từ する ở cuối chia theo thời và mức lịch sự cần dùng.", 1L },
                    { 1563703640072386669L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Add り to the ta-form to list representative activities. 休みの日は本を読んだり、映画を見たりします。 means On days off I do things such as reading and watching films.", 1563703640072386540L, "en", "Listing example activities", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "The list is illustrative. Inflect the final する for the required tense and politeness.", 1L },
                    { 1563703640072386670L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đặt lý do trước から. 今日は忙しいですから、行きません。 nghĩa là Vì hôm nay bận nên tôi không đi.", 1563703640072386541L, "vi", "Nêu lý do với から", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Với danh từ và tính từ な ở dạng ngắn khẳng định hiện tại, dùng だから, như 休みだから.", 1L },
                    { 1563703640072386671L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Put the reason before から. 今日は忙しいですから、行きません。 means I am not going because I am busy today.", 1563703640072386541L, "en", "Reasons with kara", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "In the affirmative non-past plain form, nouns and na-adjectives use だから, as in 休みだから.", 1L },
                    { 1563703640072386672L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng が để nối hai mệnh đề có ý tương phản. この店は安いですが、おいしいです。 nghĩa là Quán này rẻ mà ngon.", 1563703640072386542L, "vi", "Nối hai ý tương phản", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "が cũng có thể làm lời dẫn mềm trước một yêu cầu. Ở đây học cách dùng tương phản.", 1L },
                    { 1563703640072386673L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Use が to connect contrasting clauses. この店は安いですが、おいしいです。 means This restaurant is inexpensive but good.", 1563703640072386542L, "en", "Contrasting clauses with ga", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "が can also introduce a request gently. This point focuses on contrast.", 1L },
                    { 1563703640072386674L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Đặt đối tượng làm mốc trước より. 電車はバスより速いです。 nghĩa là Tàu điện nhanh hơn xe buýt.", 1563703640072386543L, "vi", "So sánh hai đối tượng", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Có thể hỏi bằng N1とN2と、どちらが…ですか. Câu trả lời có thể dùng Nのほうが…です.", 1L },
                    { 1563703640072386675L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Put the comparison baseline before より. 電車はバスより速いです。 means The train is faster than the bus.", 1563703640072386543L, "en", "Comparing two things", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "A question can use N1とN2と、どちらが…ですか. An answer can use Nのほうが…です.", 1L },
                    { 1563703640072386676L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nêu phạm vi bằng で, rồi dùng 一番 trước tính từ. この中で、この本が一番おもしろいです。 nghĩa là Trong số này, quyển sách này thú vị nhất.", 1563703640072386544L, "vi", "Nhất trong một phạm vi", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Cần có phạm vi so sánh rõ từ câu hoặc ngữ cảnh.", 1L },
                    { 1563703640072386677L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Mark a comparison group with で and place 一番 before the adjective. この中で、この本が一番おもしろいです。 means Of these, this book is the most interesting.", 1563703640072386544L, "en", "Superlatives within a group", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "The comparison group should be clear from the sentence or context.", 1L },
                    { 1563703640072386678L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dùng lượng từ phù hợp với vật được đếm. りんごを三つ買います。 nghĩa là Tôi mua ba quả táo. 本を二冊読みます。 nghĩa là Tôi đọc hai quyển sách.", 1563703640072386545L, "vi", "Số lượng và lượng từ", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "つ, 人, 枚, 冊 và 本 có cách dùng và biến âm riêng. Học cách đọc cùng ví dụ, như 一人（ひとり） và 三本（さんぼん）.", 1L },
                    { 1563703640072386679L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Choose a counter suited to the item. りんごを三つ買います。 means I buy three apples. 本を二冊読みます。 means I read two books.", 1563703640072386545L, "en", "Numbers and counters", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Counters such as つ, 人, 枚, 冊 and 本 have specific uses and sound changes. Learn readings in examples, such as 一人（ひとり） and 三本（さんぼん）.", 1L },
                    { 1563703640072386680L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Bỏ ます rồi dùng に trước động từ di chuyển để nêu mục đích. 本を買いに行きます。 nghĩa là Tôi đi mua sách.", 1563703640072386546L, "vi", "Đi để làm gì", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Có thể thêm địa điểm đích, như 図書館へ勉強しに行きます.", 1L },
                    { 1563703640072386681L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Remove ます and use に before a movement verb to express the purpose. 本を買いに行きます。 means I am going to buy a book.", 1563703640072386546L, "en", "Going somewhere for a purpose", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "A destination can also be included, as in 図書館へ勉強しに行きます.", 1L },
                    { 1563703640072386682L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Dạng ngắn gồm khẳng định và phủ định ở hiện tại/phi quá khứ và quá khứ. Với 食べる, bốn dạng là 食べる, 食べない, 食べた và 食べなかった. Dạng lịch sự tương ứng dùng ます hoặc です tùy từ loại.", 1563703640072386547L, "vi", "Dạng ngắn và dạng lịch sự", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Danh từ và tính từ な dùng だ trong dạng ngắn khẳng định phi quá khứ cuối câu. Lựa chọn cách nói phụ thuộc quan hệ và tình huống.", 1L },
                    { 1563703640072386683L, new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Plain forms include affirmative and negative non-past and past forms. 食べる has 食べる, 食べない, 食べた and 食べなかった. Corresponding polite forms use ます or です according to the word class.", 1563703640072386547L, "en", "Plain and polite forms", new DateTimeOffset(new DateTime(2026, 11, 7, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0)), "Nouns and na-adjectives use だ in the plain affirmative non-past sentence ending. Choose the register to suit the relationship and situation.", 1L }
                });

            migrationBuilder.InsertData(
                table: "handwriting_templates",
                columns: new[] { "id", "attribution", "created_at", "drawing", "drawing_format_version", "is_published", "license", "license_url", "revision", "source_revision", "source_url", "symbol", "updated_at", "version", "writing_system_item_id" },
